{
  "packet_id": "H6-T03-2",
  "claim_id": "C003",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C003.component",
    "value": "A missing approval attachment does not establish that approval was absent or never occurred.",
    "scope": "The evidential limit of attachment absence, including the supplied finding.",
    "provenance": {
      "refs": [
        {"source_id": "P002", "role": "SUPPORT"},
        {"source_id": "P029", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "Both spans explicitly restrict inference from attachment absence to approval absence."
    }
  },
  "signal_basis": {
    "component_id": "C003.signal_basis",
    "value": "A sampled order lacks an approval attachment in the purchasing system.",
    "scope": "The attachment gap identified for the 14 flagged sampled orders.",
    "provenance": {
      "refs": [
        {"source_id": "P001", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span identifies the affected orders and the precise documentary absence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C003.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without an unresolved empirical relation."
    }
  },
  "rationale": "Attachment absence establishes a gap in the purchasing-system record. It remains compatible with approval having occurred, so it cannot by itself establish approval absence. This licenses the frozen claim within its stated evidential limits.",
  "uncertainty": "Whether approval actually occurred remains unresolved; the claim does not assert that it did.",
  "anomalies": []
}
